+        // grid-stride loop, so larger inputs are still processed correctly.
+        constexpr int32_t max_key_grid_blocks = 65535;
+        const int32_t key_blocks =
+            std::min<int64_t>(CEILDIV(numel, key_threads), max_key_grid_blocks);
